def escaped(value) -> str:
    return html.escape(str(value), quote=True)


def _page(body: str) -> str:
    return (
        "<!doctype html><html lang='en'><head><meta charset='utf-8'>"
        "<meta name='viewport' content='width=device-width,initial-scale=1'>"
        f'<meta http-equiv="Content-Security-Policy" content="{escaped(CSP)}">'
        "<meta name='referrer' content='no-referrer'>"
        f"<title>LabRepair · Offline handover</title><style>{CSS}</style></head>"
        "<body><header><span class='brand'>LABREPAIR / HANDOVER</span>"
        "<span>READ-ONLY · OFFLINE DATA · NO DISPATCH</span></header>"
        f"<main>{body}</main></body></html>"
    )


def failure_page() -> bytes:
    """Neutral fail-closed page, without untrusted text or stale success links."""
    return _page(
        "<div class='eyebrow'>OFFLINE REPLAY FAILED</div>"
        "<h1>Handover rejected. No repair authorized.</h1>"
        "<section class='boundary failure'><h2>Independent replay did not match</h2>"
        "<p>The bundle, source pins or historical context could not be verified. "
        "No saved verdict is presented as an accepted result.</p></section>"
        "<p>No candidate was applied or executed. No provider request was made. "
        "Actual provider usage remains unknown.</p>"
        "<p class='small'>Restore a verified data handover and regenerate this "
        "read-only view. Existing downloads, if present, are historical records, "
        "not the current failed replay. No approval or dispatch action exists.</p>"
    ).encode()


def _historical_maya(raw: bytes) -> dict:
    try:
        pinned_historical_bytes(raw, DOMAIN_SHA256)
    except ValueError as exc:
        raise HandoverInvalid("HISTORICAL_DOMAIN_DIGEST_MISMATCH") from exc
    data = parse(raw)
    cases = [case for case in data["cases"] if case["case"] == "maya"]
    if (
        data["run_id"] != "20261003T194518Z-nebius-008"
        or len(cases) != 1
        or cases[0]["verdict"] != "BLOCK"
        or cases[0]["physical_interpretation"] != "NOT_ESTABLISHED"
        or cases[0]["code_repair"] != "NOT_RUN"
    ):
        raise HandoverInvalid("HISTORICAL_DOMAIN_CONTEXT_MISMATCH")
    return cases[0]


def create_view(raw: bytes, historical_domain: bytes) -> tuple[dict, dict]:
    """Freshly revalidate every bundle receipt before rendering a static view."""
    replay = replay_bundle(raw)
    maya = _historical_maya(historical_domain)
    normal, rejected = replay["cases"]["normal"], replay["cases"]["protected-change"]
    if normal["status"] != "BLOCKED" or rejected["status"] != "REJECTED":
        raise HandoverInvalid("REVIEWER_VIEW_EXPECTATION_CHANGED")
    downloads = {
        "offline-handover.json": raw,
        "fresh-replay.json": encoded(replay) + b"\n",
        "historical-domain.json": historical_domain,
    }
    hashes = {name: digest(data) for name, data in downloads.items()}
    reasons = "".join(
        f"<li><code>{escaped(reason)}</code></li>" for reason in normal["reasons"]
    )
    change = normal["candidate_review"]["changes"][0]
    binding = replay["source_bindings"]
    source_fields = {
        "Older source archive": binding["source_archive_sha256"],
        "Policy": binding["policy_sha256"],
        "Original three-file manifest": binding["workspace_manifest_sha256"],
        "Intake snapshot": binding["snapshot_sha256"],
        "Immutable suite": binding["suite_sha256"],
        "Request body": replay["request_body_sha256"],
    }
    source_rows = "".join(
        f"<dt>{escaped(name)} SHA-256</dt><dd>{escaped(value)}</dd>"
        for name, value in source_fields.items()
    )
    download_rows = "".join(
        f"<div class='download-row'><a href='{name}' download>{name}</a> "
        f"<span class='small'>({len(downloads[name])} bytes)</span>"
        f"<code>{hashes[name]}</code></div>"
        for name in sorted(DOWNLOADS)
    )
    body = (
        "<div class='eyebrow'>NEBIUS-009 · INDEPENDENT Q4 INVOICE FIXTURE</div>"
        "<h1>Two offline decisions.<br>No repair authorized.</h1>"
        "<p class='intro'>The handover matches a fresh local replay. "
        "That establishes consistency of two saved offline decisions, "
        "not a successful code repair, a model run or a cloud deployment.</p>"
        "<section class='boundary' aria-label='Replay boundary'>"
        "<strong>REPLAY MATCHED ≠ REPAIR APPROVED</strong>"
        "<p>Source: verified pinned older snapshot. Latest remote match: UNVERIFIED.</p>"
        "<p>No Run, Approve or Apply action. Checksums detect changes; they are not signatures.</p>"
        "</section><div class='metrics' aria-label='Actual capability evidence'>"
        "<div><span>NVIDIA / Nebius model</span><b>NOT_RUN</b></div>"
        "<div><span>Isolated candidate execution</span><b>NOT_RUN</b></div>"
        "<div><span>Actual provider usage</span><b>unknown</b></div>"
        "<div><span>Candidate source written</span><b>false</b></div></div>"
        "<nav aria-label='Review sections'><a href='#decisions'>Decisions</a>"
        "<a href='#bindings'>Source bindings</a><a href='#downloads'>Download evidence</a></nav>"
        "<div class='columns'><div><section class='panel' id='decisions'>"
        "<div class='case-head'><h2>01 · Bounded ledger proposal</h2>"
        "<span class='badge blocked'>BLOCKED</span></div>"
        "<p class='small'>Reviewed literal response fixture, not NVIDIA output. "
        "Only ledger.py is editable as a proposal; no source is changed.</p>"
        f"<ul class='reasons'>{reasons}</ul>"
        f"<h3>{escaped(change['path'])} · candidate text only</h3>"
        f"<pre>{escaped(change['diff'])}</pre><dl><dt>Before SHA-256</dt>"
        f"<dd>{escaped(change['before_sha256'])}</dd><dt>After SHA-256</dt>"
        f"<dd>{escaped(change['after_sha256'])}</dd></dl>"
        "<p class='small'>A reviewable diff is not a tested diff. "
        "Verified isolation and an enforceable spending limit are still required.</p></section>"
        "<section class='panel'><div class='case-head'><h2>02 · Protected runner change</h2>"
        "<span class='badge rejected'>REJECTED</span></div>"
        f"<p><code>{escaped(rejected['reasons'][0])}</code></p>"
        "<p class='small'>No valid diff is released by the gate. The immutable test "
        "runner cannot be changed to make a candidate appear successful.</p></section>"
        "<details id='bindings'><summary>Inspect exact source and request bindings</summary>"
        f"<div class='detail-body'><dl>{source_rows}</dl>"
        "<p class='small'>Independent operator pins are reloaded during replay. "
        "A model-owned manifest, rehashed verdict or readiness flag cannot override them.</p>"
        "</div></details></div><aside><section class='panel'>"
        "<h3>Original science · separate record</h3>"
        "<p class='small'>Saved NEBIUS-008 synthetic Maya replay. "
        "The invoice proposal above does not repair or re-evaluate this Bell/CHSH claim.</p>"
        f"<div class='value-row'><span>Submitted S</span><b>{escaped(maya['claimed_s'])}</b></div>"
        f"<div class='value-row'><span>Registered replay S</span><b>{escaped(maya['replayed_s'])}</b></div>"
        "<p><span class='badge blocked'>Original claim: BLOCK</span></p>"
        f"<p class='small'>Claim: {escaped(maya['claim_state'])}<br>"
        f"Physical interpretation: {escaped(maya['physical_interpretation'])}</p>"
        "<p class='small'>No scientific repair ran. Finite artifact replay does not "
        "certify nature, quantum advantage or a loophole-free Bell test.</p></section>"
        "<section class='panel'><h3>Next evidence gates</h3><ol class='steps'>"
        "<li>Verify account model entitlement, covered free credits and an enforceable spending cap.</li>"
        "<li>Verify an actual isolated backend and protected-test policy independently.</li>"
        "<li>Only then perform the bounded real inference and isolated candidate test; "
        "preserve usage and recovery receipts.</li></ol>"
        "<p class='small'>No key, account change or paid resource is requested by this page.</p>"
        "</section></aside></div><section class='panel downloads' id='downloads'>"
        "<h2>Replayable evidence, not an approval token</h2>"
        f"<p class='small'>View run: {RUN_ID}. Fresh replay uses NEBIUS-008 handover "
        f"data originating from {escaped(replay['origin_run_id'])}. Download hashes "
        "refer to exact static bytes. Historical science keeps its saved run identity.</p>"
        f"{download_rows}</section><footer>Local static preview only. No provider transport, "
        "arbitrary-code execution, approval writes, external page assets, private research "
        "or credentials. The archived NEBIUS-005 view and original source remain unchanged.</footer>"
    )
    page = _page(body).encode()
    files = {**downloads, "index.html": page}
    receipt = {
        "run_id": RUN_ID,
        "mode": "FRESH_OFFLINE_REPLAY_STATIC_READ_ONLY_VIEW",
        "output": "handover-workbench/index.html",
        "html_sha256": digest(page),
        "html_bytes": len(page),
        "download_sha256": hashes,
        "historical_domain_original_crlf_sha256": DOMAIN_SHA256,
        "historical_domain_bytes_restoration_verified": True,
        "bundle_sha256": replay["bundle_sha256"],
        "replay": replay["verification"],
        "source_pins_reloaded": True,
        "normal": "BLOCKED",
        "protected_change": "REJECTED PROTECTED_FILE_CHANGE",
        "historical_science_run": "20261003T194518Z-nebius-008",
        "scientific_repair": "NOT_RUN",
        "model": "NOT_RUN",
        "candidate_execution": "NOT_RUN",
        "actual_provider_usage": "unknown",
        "static_files": sorted(files),
    }
    return files, receipt


def _output_root() -> Path:
    output = ROOT / "handover-workbench"
    for path in (output, output / "qa"):
        if any(item.is_symlink() for item in (path, *path.parents)):
            raise HandoverInvalid("OUTPUT_SYMLINK_FORBIDDEN")
    if output.exists() and any(
        item.name not in {*DOWNLOADS, "index.html", "qa"}
        or item.is_symlink()
        or (item.name == "qa" and not item.is_dir())
        or (item.name != "qa" and not item.is_file())
        for item in output.iterdir()
    ):
        raise HandoverInvalid("UNEXPECTED_STATIC_OUTPUT")
    qa = output / "qa"
    if qa.exists() and any(
        item.name != "rejected.html" or item.is_symlink() or not item.is_file()
        for item in qa.iterdir()
    ):
        raise HandoverInvalid("UNEXPECTED_QA_OUTPUT")
    output.mkdir(exist_ok=True)
    return output


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--input", type=Path, default=ROOT / "evidence/nebius_008_handover.json"
    )
    parser.add_argument("--rejected-preview", action="store_true")
    args = parser.parse_args()
    if not args.input.resolve().is_relative_to((ROOT / "evidence").resolve()):
        parser.error("input must remain inside the reviewed evidence folder")
    output = _output_root()
    target = (
        output / "qa/rejected.html" if args.rejected_preview else output / "index.html"
    )
    try:
        files, receipt = create_view(
            _read_bounded(args.input, MAX_BUNDLE_BYTES),
            _read_bounded(DOMAIN_PATH, 65536),
        )
        if args.rejected_preview:
            raise HandoverInvalid("NEGATIVE_PREVIEW_EXPECTED_INVALID_INPUT")
        # Page last: an incomplete write is not shown as a successful generation.
        for name, data in files.items():
            (output / name).write_bytes(data)
        receipt["generated_at_utc"] = datetime.now(timezone.utc).isoformat()
        receipt["download_readback"] = all(
            (output / name).read_bytes() == data for name, data in files.items()
        )
        report = ROOT / "evidence/nebius_009_workbench.json"
        if report.is_symlink():
            raise HandoverInvalid("RECEIPT_SYMLINK_FORBIDDEN")
        report.write_text(json.dumps(receipt, indent=2) + "\n", encoding="utf-8")
        print(json.dumps(receipt))
        return 0
    except (HandoverInvalid, SourceUnavailable, OSError):
        # Do not echo untrusted data, paths or errors. No stale success links.
        target.parent.mkdir(exist_ok=True)
        target.write_bytes(failure_page())
        print(json.dumps({"run_id": RUN_ID, "view": "REJECTED", "model": "NOT_RUN"}))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
